package main

import (
	"bufio"
	"fmt"
	"os"
	"strconv"
	"strings"

	"github.com/shopspring/decimal"
)

type AmtRec struct {
	ArAcct string
	ArAmt  decimal.Decimal
}

var WsEofFlag string = "N"
var WsBigTotal decimal.Decimal = decimal.NewFromInt(0)
var WsWrapTotal decimal.Decimal = decimal.NewFromInt(0)
var WsSafeTotal decimal.Decimal = decimal.NewFromInt(0)
var WsOverflows int64 = 0
var WsCount int64 = 0
var WsHalf decimal.Decimal = decimal.NewFromInt(0)
var WsAmtEd string
var WsWrapEd string
var WsSafeEd string
var WsHalfEd string

var curRec AmtRec
var inputRecords []string
var inputPos int

func pow10Decimal(n int) decimal.Decimal {
	return decimal.NewFromInt(1).Shift(int32(n))
}

func maxForPic(intDigits, scale int) decimal.Decimal {
	total := intDigits + scale
	pow10 := pow10Decimal(total)
	maxInt := pow10.Sub(decimal.NewFromInt(1))
	return maxInt.Shift(int32(-scale))
}

func fitsInPic(val decimal.Decimal, intDigits, scale int) bool {
	if val.Sign() < 0 {
		return false
	}
	max := maxForPic(intDigits, scale)
	tv := val.Truncate(int32(scale))
	return tv.Cmp(max) <= 0
}

func storeTruncate(val decimal.Decimal, intDigits, scale int) decimal.Decimal {
	scaled := val.Shift(int32(scale)).Truncate(0)
	scaledInt := scaled.IntPart()
	total := intDigits + scale
	modBase := int64(1)
	for i := 0; i < total; i++ {
		modBase *= 10
	}
	rem := scaledInt % modBase
	return decimal.New(rem, int32(-scale))
}

func storeTruncateInt(val int64, digits int) int64 {
	mod := int64(1)
	for i := 0; i < digits; i++ {
		mod *= 10
	}
	return val % mod
}

func formatEdited(val decimal.Decimal, pic string) string {
	parts := strings.Split(pic, ".")
	intPat := parts[0]
	fracPat := ""
	if len(parts) > 1 {
		fracPat = parts[1]
	}
	intDigits := 0
	for _, c := range intPat {
		if c == 'Z' || c == '9' {
			intDigits++
		}
	}
	fracDigits := 0
	for _, c := range fracPat {
		if c == 'Z' || c == '9' {
			fracDigits++
		}
	}
	absVal := val.Abs()
	scaled := absVal.Shift(int32(fracDigits)).Truncate(0)
	scaledInt := scaled.IntPart()
	var powInt int64 = 1
	for i := 0; i < fracDigits; i++ {
		powInt *= 10
	}
	var intPartInt int64
	var fracPartInt int64
	if fracDigits == 0 {
		intPartInt = scaledInt
		fracPartInt = 0
	} else {
		intPartInt = scaledInt / powInt
		fracPartInt = scaledInt % powInt
		if intPartInt < 0 {
			intPartInt = -intPartInt
		}
		if fracPartInt < 0 {
			fracPartInt = -fracPartInt
		}
	}
	intStr := strconv.FormatInt(intPartInt, 10)
	if len(intStr) > intDigits {
		intStr = intStr[len(intStr)-intDigits:]
	} else if len(intStr) < intDigits {
		intStr = strings.Repeat("0", intDigits-len(intStr)) + intStr
	}
	var intFormatted strings.Builder
	suppression := true
	digitIdx := 0
	for _, ch := range intPat {
		if ch == 'Z' || ch == '9' {
			d := intStr[digitIdx]
			digitIdx++
			if suppression {
				if ch == 'Z' && d == '0' {
					intFormatted.WriteByte(' ')
				} else {
					intFormatted.WriteByte(d)
					suppression = false
				}
			} else {
				intFormatted.WriteByte(d)
			}
		} else if ch == ',' {
			if suppression {
				intFormatted.WriteByte(' ')
			} else {
				intFormatted.WriteByte(',')
			}
		} else {
			intFormatted.WriteByte(byte(ch))
		}
	}
	result := intFormatted.String()
	if fracDigits > 0 {
		fracFormatted := fmt.Sprintf("%0*d", fracDigits, fracPartInt)
		result += "." + fracFormatted
	}
	return result
}

func formatPic99(v int64, digits int) string {
	return fmt.Sprintf("%0*d", digits, v)
}

func loadInput() {
	f, err := os.Open("input.dat")
	if err != nil {
		inputRecords = []string{}
		return
	}
	defer f.Close()
	scanner := bufio.NewScanner(f)
	buf := make([]byte, 0, 64*1024)
	scanner.Buffer(buf, 1024*1024)
	for scanner.Scan() {
		line := scanner.Text()
		inputRecords = append(inputRecords, line)
	}
}

func READPARA() {
	if inputPos >= len(inputRecords) {
		WsEofFlag = "Y"
		return
	}
	line := inputRecords[inputPos]
	inputPos++
	if len(line) < 11 {
		line = line + strings.Repeat(" ", 11-len(line))
	} else if len(line) > 11 {
		line = line[:11]
	}
	curRec.ArAcct = line[0:4]
	amtStr := line[4:11]
	s := strings.TrimSpace(amtStr)
	if s == "" {
		curRec.ArAmt = decimal.NewFromInt(0)
	} else {
		n, err := strconv.ParseInt(s, 10, 64)
		if err != nil {
			d, err2 := decimal.NewFromString(s)
			if err2 != nil {
				d = decimal.NewFromInt(0)
			}
			curRec.ArAmt = d.Shift(-2)
		} else {
			curRec.ArAmt = decimal.New(n, -2)
		}
	}
	WsEofFlag = "N"
}

func OVERFLOWPARA() {
	WsOverflows = storeTruncateInt(WsOverflows+1, 2)
}

func PROCESSPARA() {
	WsBigTotal = storeTruncate(WsBigTotal.Add(curRec.ArAmt), 7, 2)
	WsWrapTotal = storeTruncate(WsBigTotal, 5, 2)
	sum := WsSafeTotal.Add(curRec.ArAmt)
	if fitsInPic(sum, 5, 2) {
		WsSafeTotal = sum
	} else {
		OVERFLOWPARA()
	}
	WsCount = storeTruncateInt(WsCount+1, 2)
	raw := curRec.ArAmt.Mul(decimal.NewFromInt(5)).Shift(-1)
	WsHalf = storeTruncate(raw, 5, 1)
	WsAmtEd = formatEdited(curRec.ArAmt, "ZZ,ZZ9.99")
	WsWrapEd = formatEdited(WsWrapTotal, "ZZ,ZZ9.99")
	WsSafeEd = formatEdited(WsSafeTotal, "ZZ,ZZ9.99")
	WsHalfEd = formatEdited(WsHalf, "ZZ,ZZ9.9")
	fmt.Printf("%s %s %s %s %s\n", curRec.ArAcct, WsAmtEd, WsWrapEd, WsSafeEd, WsHalfEd)
	READPARA()
}

func SUMMARYPARA() {
	fmt.Printf("RECORDS: %s\n", formatPic99(WsCount, 2))
	fmt.Printf("OVERFLOWS: %s\n", formatPic99(WsOverflows, 2))
}

func MAINPARA() {
	loadInput()
	READPARA()
	for WsEofFlag != "Y" {
		PROCESSPARA()
	}
	SUMMARYPARA()
}

func main() {
	MAINPARA()
}
